<script setup lang="ts">
import { onMounted, reactive } from 'vue'; import { storeToRefs } from 'pinia'; import { useSettingsStore } from '../runtime/settings-store'; import SettingsSubnav from '../components/SettingsSubnav.vue'; import SettingsScenarioBar from '../components/SettingsScenarioBar.vue'; import './settings-views.css'
const store=useSettingsStore(); const { auditLogs, loading, error, scenario, actor }=storeToRefs(store); const query=reactive({keyword:'',from:'',to:''}); onMounted(()=>store.load()); async function search(){await store.queryAuditLogs({...query})} function exportCsv(){const blob=new Blob([store.exportAuditCsv({...query})],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='system-audit-logs.csv';a.click();URL.revokeObjectURL(url)}
</script>
<template><section class="settings-page"><header class="settings-header"><div><p class="eyebrow">SET-004 · 审计</p><h1>系统日志</h1><p>日志只追加不可编辑或删除；导出只生成当前筛选的 fake CSV。</p></div><SettingsScenarioBar :scenario="scenario" :role="actor.role" @scenario="store.setScenario" @role="store.setRole"/></header><SettingsSubnav/><div v-if="error" class="settings-warning" role="alert">{{error}} <button class="set-button" @click="store.load">重试</button></div><div class="settings-panel"><div class="settings-toolbar settings-log-filters"><label>关键字<input v-model.trim="query.keyword" placeholder="操作、操作人、对象"></label><label>开始日期<input v-model="query.from" type="date"></label><label>结束日期<input v-model="query.to" type="date"></label><button class="set-button primary" @click="search">查询</button><button class="set-button" :disabled="actor.role!=='super-admin'" @click="exportCsv">导出 CSV</button></div><div v-if="loading" class="settings-state">正在加载日志…</div><div v-else-if="!auditLogs.length" class="settings-state">暂无符合条件的日志</div><div v-else class="settings-table-wrap"><table class="settings-table"><thead><tr><th>时间</th><th>操作人</th><th>操作类型</th><th>对象</th><th>详情</th></tr></thead><tbody><tr v-for="item in auditLogs" :key="item.id"><td>{{item.createdAt}}</td><td>{{item.operatorId}}</td><td>{{item.action}}</td><td>{{item.targetId}}</td><td>{{item.detail}}</td></tr></tbody></table></div></div></section></template>
